/*
 * kmem.c — WDM kernel driver: cross-process virtual memory read/write
 *
 * Device : \Device\KMem
 * Symlink: \DosDevices\KMem
 *
 * IOCTLs (METHOD_BUFFERED):
 *
 *   IOCTL_KMEM_READ
 *     In  : KMEM_REQUEST
 *     Out : raw bytes read from Address in the target process
 *
 *   IOCTL_KMEM_WRITE
 *     In  : KMEM_REQUEST followed immediately by the bytes to write
 *     Out : none  (IoStatus.Information = bytes actually written)
 *
 * Both IOCTLs accept ProcessId == NULL to target the calling process.
 *
 * Build: WDK 10, x64, C, /W4 /WX
 */

#include <ntddk.h>
#include <wdm.h>

/* ── constants ─────────────────────────────────────────────────────────── */

#define DEVICE_NAME     L"\\Device\\KMem"
#define SYMLINK_NAME    L"\\DosDevices\\KMem"
#define KMEM_POOL_TAG   'meMK'

#define IOCTL_KMEM_READ  \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_KMEM_WRITE \
    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* ── public request structure (share with user-mode callers) ───────────── */

typedef struct _KMEM_REQUEST {
    HANDLE  ProcessId;  /* target PID; NULL → caller's own process */
    PVOID   Address;    /* virtual address in that process          */
    SIZE_T  Size;       /* byte count to transfer                   */
} KMEM_REQUEST, *PKMEM_REQUEST;

/* ── MmCopyVirtualMemory (undocumented, stable since Vista) ────────────── */

NTSTATUS
NTAPI
MmCopyVirtualMemory(
    _In_  PEPROCESS         SourceProcess,
    _In_  PVOID             SourceAddress,
    _In_  PEPROCESS         TargetProcess,
    _Out_ PVOID             TargetAddress,
    _In_  SIZE_T            BufferSize,
    _In_  KPROCESSOR_MODE   PreviousMode,
    _Out_ PSIZE_T           ReturnSize
);

/* ── forward declarations ──────────────────────────────────────────────── */

static DRIVER_UNLOAD    KMemUnload;
static DRIVER_DISPATCH  KMemCreateClose;
static DRIVER_DISPATCH  KMemDeviceControl;

/* ── globals ───────────────────────────────────────────────────────────── */

static PDEVICE_OBJECT g_DeviceObject = NULL;

/* ── helpers ───────────────────────────────────────────────────────────── */

/*
 * Resolve a PID to a referenced PEPROCESS.
 * Returns the current process (also referenced) when pid is NULL.
 */
static NTSTATUS
KMemLookupProcess(
    _In_  HANDLE     Pid,
    _Out_ PEPROCESS *OutProcess
)
{
    if (Pid == NULL || Pid == PsGetCurrentProcessId()) {
        *OutProcess = PsGetCurrentProcess();
        ObReferenceObject(*OutProcess);
        return STATUS_SUCCESS;
    }
    return PsLookupProcessByProcessId(Pid, OutProcess);
}

/* ── IRP handlers ──────────────────────────────────────────────────────── */

static NTSTATUS
KMemUnload(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    UNICODE_STRING symlink = RTL_CONSTANT_STRING(SYMLINK_NAME);
    IoDeleteSymbolicLink(&symlink);

    if (g_DeviceObject != NULL) {
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
    }

    UNREFERENCED_PARAMETER(DriverObject);
    return STATUS_SUCCESS;
}

/* Satisfy the DRIVER_UNLOAD typedef (void return) */
static VOID
KMemUnloadVoid(
    _In_ PDRIVER_OBJECT DriverObject
)
{
    KMemUnload(DriverObject);
}

static NTSTATUS
KMemCreateClose(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    Irp->IoStatus.Status      = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS
KMemDeviceControl(
    _In_ PDEVICE_OBJECT DeviceObject,
    _In_ PIRP           Irp
)
{
    UNREFERENCED_PARAMETER(DeviceObject);

    PIO_STACK_LOCATION stack  = IoGetCurrentIrpStackLocation(Irp);
    ULONG  code    = stack->Parameters.DeviceIoControl.IoControlCode;
    ULONG  inLen   = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG  outLen  = stack->Parameters.DeviceIoControl.OutputBufferLength;
    PVOID  sysBuf  = Irp->AssociatedIrp.SystemBuffer;

    NTSTATUS status      = STATUS_INVALID_PARAMETER;
    SIZE_T   transferred = 0;

    switch (code) {

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_READ: {
        /*
         * Caller supplies a KMEM_REQUEST as input.
         * The driver copies up to min(outLen, req.Size) bytes starting at
         * req.Address in req.ProcessId into the output portion of the
         * METHOD_BUFFERED system buffer.
         *
         * With METHOD_BUFFERED the kernel allocates one buffer of
         * max(inLen, outLen) bytes.  We capture all input fields before
         * writing to the buffer so the input and output regions can safely
         * overlap when outLen < sizeof(KMEM_REQUEST).
         */
        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        /* Capture request fields before any write-back. */
        PKMEM_REQUEST req       = (PKMEM_REQUEST)sysBuf;
        HANDLE        pid       = req->ProcessId;
        PVOID         addr      = req->Address;
        SIZE_T        copySize  = min((SIZE_T)outLen, req->Size);

        if (copySize == 0) {
            status = STATUS_SUCCESS;
            break;
        }

        PEPROCESS targetProcess = NULL;
        status = KMemLookupProcess(pid, &targetProcess);
        if (!NT_SUCCESS(status)) break;

        /*
         * Stage the copy in a non-paged kernel buffer, then write the
         * result into sysBuf.  Staging avoids aliasing issues when the
         * target happens to be the current process and src/dst overlap.
         */
        PVOID staging = ExAllocatePoolWithTag(NonPagedPool, copySize, KMEM_POOL_TAG);
        if (staging == NULL) {
            ObDereferenceObject(targetProcess);
            status = STATUS_INSUFFICIENT_RESOURCES;
            break;
        }

        status = MmCopyVirtualMemory(
            targetProcess,          /* source process          */
            addr,                   /* source address          */
            PsGetCurrentProcess(),  /* destination process     */
            staging,                /* destination (kernel)    */
            copySize,
            KernelMode,
            &transferred
        );

        ObDereferenceObject(targetProcess);

        if (NT_SUCCESS(status) && transferred > 0) {
            RtlCopyMemory(sysBuf, staging, transferred);
        }

        ExFreePoolWithTag(staging, KMEM_POOL_TAG);
        break;
    }

    /* ------------------------------------------------------------------ */
    case IOCTL_KMEM_WRITE: {
        /*
         * Caller supplies a KMEM_REQUEST followed immediately by the bytes
         * to write.  The driver copies min(dataLen, req.Size) bytes from
         * that payload into req.Address in req.ProcessId.
         *
         * Input layout (all in sysBuf):
         *   [KMEM_REQUEST][... data bytes ...]
         */
        if (inLen < sizeof(KMEM_REQUEST)) {
            status = STATUS_BUFFER_TOO_SMALL;
            break;
        }

        PKMEM_REQUEST req      = (PKMEM_REQUEST)sysBuf;
        HANDLE        pid      = req->ProcessId;
        PVOID         addr     = req->Address;
        SIZE_T        dataLen  = (SIZE_T)inLen - sizeof(KMEM_REQUEST);
        PVOID         data     = (PUCHAR)sysBuf + sizeof(KMEM_REQUEST);
        SIZE_T        copySize = min(dataLen, req->Size);

        if (copySize == 0) {
            status = STATUS_SUCCESS;
            break;
        }

        PEPROCESS targetProcess = NULL;
        status = KMemLookupProcess(pid, &targetProcess);
        if (!NT_SUCCESS(status)) break;

        /*
         * Stage the payload so we have a stable kernel pointer independent
         * of the system buffer before we reference the target process.
         */
        PVOID staging = ExAllocatePoolWithTag(NonPagedPool, copySize, KMEM_POOL_TAG);
        if (staging == NULL) {
            ObDereferenceObject(targetProcess);
            status = STATUS_INSUFFICIENT_RESOURCES;
            break;
        }

        RtlCopyMemory(staging, data, copySize);

        status = MmCopyVirtualMemory(
            PsGetCurrentProcess(),  /* source process (kernel staging buf) */
            staging,                /* source address                       */
            targetProcess,          /* destination process                  */
            addr,                   /* destination address                  */
            copySize,
            KernelMode,
            &transferred
        );

        ObDereferenceObject(targetProcess);
        ExFreePoolWithTag(staging, KMEM_POOL_TAG);
        break;
    }

    /* ------------------------------------------------------------------ */
    default:
        status = STATUS_INVALID_DEVICE_REQUEST;
        break;
    }

    Irp->IoStatus.Status      = status;
    Irp->IoStatus.Information = NT_SUCCESS(status) ? transferred : 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return status;
}

/* ── DriverEntry ───────────────────────────────────────────────────────── */

NTSTATUS
DriverEntry(
    _In_ PDRIVER_OBJECT  DriverObject,
    _In_ PUNICODE_STRING RegistryPath
)
{
    UNREFERENCED_PARAMETER(RegistryPath);

    UNICODE_STRING devName = RTL_CONSTANT_STRING(DEVICE_NAME);
    UNICODE_STRING symlink = RTL_CONSTANT_STRING(SYMLINK_NAME);
    NTSTATUS status;

    status = IoCreateDevice(
        DriverObject,
        0,
        &devName,
        FILE_DEVICE_UNKNOWN,
        FILE_DEVICE_SECURE_OPEN,
        FALSE,          /* not exclusive */
        &g_DeviceObject
    );
    if (!NT_SUCCESS(status)) return status;

    status = IoCreateSymbolicLink(&symlink, &devName);
    if (!NT_SUCCESS(status)) {
        IoDeleteDevice(g_DeviceObject);
        g_DeviceObject = NULL;
        return status;
    }

    DriverObject->DriverUnload                          = KMemUnloadVoid;
    DriverObject->MajorFunction[IRP_MJ_CREATE]         = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = KMemCreateClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = KMemDeviceControl;

    /* METHOD_BUFFERED does not need DO_BUFFERED_IO; clear the init flag. */
    g_DeviceObject->Flags &= ~DO_DEVICE_INITIALIZING;

    return STATUS_SUCCESS;
}
